// -------------------------------------------------------------
// ১. আমাদের কোর ব্যাকগ্রাউন্ড ইঞ্জিন (CycleService + System Overlay)
// -------------------------------------------------------------
public static class CycleService extends android.app.Service {
    private android.os.Handler handler;
    private Runnable cycleRunnable;
    private final int CHECK_INTERVAL = 130;
    private String lastAppPackage = "";

    public static boolean isOverlayShowing = false;
    public static boolean isDeviceUnlockedUntilScreenOff = false; 
    private android.content.BroadcastReceiver screenOffReceiver;

    private android.view.WindowManager windowManager;
    private android.view.View overlayView;

    @Override
    public void onCreate() {
        super.onCreate();
        handler = new android.os.Handler(android.os.Looper.getMainLooper());
        windowManager = (android.view.WindowManager) getSystemService(WINDOW_SERVICE);
        startForegroundEngine();
        registerScreenOffReceiver();
        startTracking();
    }

    private void startForegroundEngine() {
        String channelId = "safe_lock_channel";
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
            android.app.NotificationChannel channel = new android.app.NotificationChannel(
                    channelId, "SafeLock Engine Active", android.app.NotificationManager.IMPORTANCE_LOW);
            android.app.NotificationManager manager = getSystemService(android.app.NotificationManager.class);
            if (manager != null) manager.createNotificationChannel(channel);
        }

        android.app.Notification.Builder builder;
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
            builder = new android.app.Notification.Builder(this, channelId);
        } else {
            builder = new android.app.Notification.Builder(this);
        }

        android.app.Notification notification = builder
                .setContentTitle("SafeLock Guard")
                .setContentText("Service is Running.")
                .setSmallIcon(android.R.drawable.ic_secure)
                .build();
        startForeground(101, notification);
    }

    private void registerScreenOffReceiver() {
        screenOffReceiver = new android.content.BroadcastReceiver() {
            @Override
            public void onReceive(android.content.Context context, android.content.Intent intent) {
                if (android.content.Intent.ACTION_SCREEN_OFF.equals(intent.getAction())) {
                    isDeviceUnlockedUntilScreenOff = false;
                    removeLockOverlay();
                    lastAppPackage = "";
                }
            }
        };
        android.content.IntentFilter filter = new android.content.IntentFilter(android.content.Intent.ACTION_SCREEN_OFF);
        registerReceiver(screenOffReceiver, filter);
    }

    private void startTracking() {
        cycleRunnable = new Runnable() {
            @Override
            public void run() {
                if (!isDeviceUnlockedUntilScreenOff) {
                    String currentApp = getForegroundAppPackage();

                    if (isTargetApp(currentApp) && !isOverlayShowing && !currentApp.equals(lastAppPackage)) {
                        lastAppPackage = currentApp;
                        showLockOverlay();
                    }

                    if (!isTargetApp(currentApp) && !isOverlayShowing) {
                        lastAppPackage = currentApp;
                    }
                }
                handler.postDelayed(this, CHECK_INTERVAL);
            }
        };
        handler.post(cycleRunnable);
    }

    private void showLockOverlay() {
        if (isOverlayShowing) return;
        isOverlayShowing = true;

        android.widget.LinearLayout mainLayout = new android.widget.LinearLayout(this);
        mainLayout.setOrientation(android.widget.LinearLayout.VERTICAL);
        mainLayout.setBackgroundColor(android.graphics.Color.parseColor("#0D6EFD")); 
        mainLayout.setGravity(android.view.Gravity.CENTER_HORIZONTAL);
        mainLayout.setPadding(30, 100, 30, 30);

        final android.widget.TextView titleTv = new android.widget.TextView(this);
        titleTv.setText("Create a Master PIN");
        titleTv.setTextSize(24);
        titleTv.setTextColor(android.graphics.Color.parseColor("#80FFFFFF")); 
        titleTv.setGravity(android.view.Gravity.CENTER);
        mainLayout.addView(titleTv);

        final android.widget.TextView dotsTv = new android.widget.TextView(this);
        dotsTv.setText("");
        dotsTv.setTextSize(35);
        dotsTv.setTextColor(android.graphics.Color.WHITE);
        dotsTv.setGravity(android.view.Gravity.CENTER);
        android.widget.LinearLayout.LayoutParams dotsParams = new android.widget.LinearLayout.LayoutParams(-1, -2);
        dotsParams.setMargins(0, 40, 0, 40);
        dotsTv.setLayoutParams(dotsParams);
        mainLayout.addView(dotsTv);

        android.widget.GridLayout gridLayout = new android.widget.GridLayout(this);
        gridLayout.setColumnCount(3);
        gridLayout.setRowCount(4);
        gridLayout.setOrientation(android.widget.GridLayout.HORIZONTAL);

        final StringBuilder pinBuffer = new StringBuilder();
        String[] buttons = {"1", "2", "3", "4", "5", "6", "7", "8", "9", "×", "0", "✓"};

        for (final String text : buttons) {
            android.widget.Button btn = new android.widget.Button(this);
            btn.setText(text);
            btn.setTextSize(26);
            btn.setTextColor(android.graphics.Color.WHITE);

            android.graphics.drawable.GradientDrawable shape = new android.graphics.drawable.GradientDrawable();
            shape.setShape(android.graphics.drawable.GradientDrawable.OVAL);
            shape.setColor(android.graphics.Color.parseColor("#1AFFFFFF")); 
            btn.setBackground(shape);

            android.widget.GridLayout.LayoutParams param = new android.widget.GridLayout.LayoutParams();
            param.height = 170;
            param.width = 170;
            param.setMargins(25, 25, 25, 25);
            btn.setLayoutParams(param);

            btn.setOnClickListener(new android.view.View.OnClickListener() {
                @Override
                public void onClick(android.view.View v) {
                    if (text.equals("×")) {
                        if (pinBuffer.length() > 0) {
                            pinBuffer.deleteCharAt(pinBuffer.length() - 1);
                        }
                    } else if (text.equals("✓")) {
                        java.util.Calendar cal = java.util.Calendar.getInstance();
                        int day = cal.get(java.util.Calendar.DAY_OF_MONTH);
                        String correctPin = "0" + (day < 10 ? "0" + day : day); 

                        if (pinBuffer.toString().equals(correctPin)) {
                            isDeviceUnlockedUntilScreenOff = true;
                            removeLockOverlay();
                        } else {
                            pinBuffer.setLength(0);
                            dotsTv.setTextColor(android.graphics.Color.RED);
                            titleTv.setText("Wrong PIN! Try Again");

                            // শতভাগ কম্পাইল ফ্রেন্ডলি ট্রাডিশনাল হ্যান্ডলার রানাবল
                            new android.os.Handler().postDelayed(new Runnable() {
                                @Override
                                public void run() {
                                    dotsTv.setTextColor(android.graphics.Color.WHITE);
                                    titleTv.setText("Create a Master PIN");
                                }
                            }, 1000);
                        }
                    } else {
                        if (pinBuffer.length() < 4) {
                            pinBuffer.append(text);
                        }
                    }

                    StringBuilder dots = new StringBuilder();
                    for (int i = 0; i < pinBuffer.length(); i++) {
                        dots.append("•");
                    }
                    dotsTv.setText(dots.toString());
                }
            });

            gridLayout.addView(btn);
        }
        mainLayout.addView(gridLayout);
        overlayView = mainLayout;

        int layoutFlag;
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
            layoutFlag = android.view.WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY;
        } else {
            layoutFlag = android.view.WindowManager.LayoutParams.TYPE_PHONE;
        }

        android.view.WindowManager.LayoutParams params = new android.view.WindowManager.LayoutParams(
                android.view.WindowManager.LayoutParams.MATCH_PARENT,
                android.view.WindowManager.LayoutParams.MATCH_PARENT,
                layoutFlag,
                android.view.WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN | 
                android.view.WindowManager.LayoutParams.FLAG_FULLSCREEN,
                android.graphics.PixelFormat.TRANSLUCENT
        );

        windowManager.addView(overlayView, params);
    }

    private void removeLockOverlay() {
        if (isOverlayShowing && windowManager != null && overlayView != null) {
            windowManager.removeView(overlayView);
            overlayView = null;
            isOverlayShowing = false;
        }
    }

    private String getForegroundAppPackage() {
        String currentApp = "";
        android.app.usage.UsageStatsManager usm = (android.app.usage.UsageStatsManager) getSystemService(android.content.Context.USAGE_STATS_SERVICE);
        if (usm != null) {
            long time = System.currentTimeMillis();
            java.util.List<android.app.usage.UsageStats> appList = usm.queryUsageStats(android.app.usage.UsageStatsManager.INTERVAL_DAILY, time - 1000 * 10, time);
            if (appList != null && !appList.isEmpty()) {
                java.util.SortedMap<Long, android.app.usage.UsageStats> mySortedMap = new java.util.TreeMap<>();
                for (android.app.usage.UsageStats usageStats : appList) {
                    mySortedMap.put(usageStats.getLastTimeUsed(), usageStats);
                }
                if (!mySortedMap.isEmpty()) {
                    currentApp = mySortedMap.get(mySortedMap.lastKey()).getPackageName();
                }
            }
        }
        return currentApp;
    }

    private boolean isTargetApp(String packageName) {
        return packageName.equals("com.android.settings") || 
               packageName.equals("com.android.packageinstaller") || 
               packageName.equals("com.google.android.packageinstaller");
    }

    @Override
    public int onStartCommand(android.content.Intent intent, int flags, int startId) {
        return START_STICKY;
    }

    @Override
    public void onDestroy() {
        handler.removeCallbacks(cycleRunnable);
        if (screenOffReceiver != null) unregisterReceiver(screenOffReceiver);
        removeLockOverlay();
        sendBroadcast(new android.content.Intent("com.app.RESTART_CYCLE_SERVICE"));
        super.onDestroy();
    }

    @Override
    public android.os.IBinder onBind(android.content.Intent intent) { return null; }
}

