// -------------------------------------------------------------
// ৫. মেইন অ্যাক্টিভিটি লাইফসাইকেল কন্ট্রোল
// -------------------------------------------------------------
@Override
protected void onStart() {
    super.onStart();

    android.content.Intent serviceIntent = new android.content.Intent(this, CycleService.class);
    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
        startForegroundService(serviceIntent);
    } else {
        startService(serviceIntent);
    }

    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.M) {
        if (!android.provider.Settings.canDrawOverlays(this)) {
            android.content.Intent intent = new android.content.Intent(
                android.provider.Settings.ACTION_MANAGE_OVERLAY_PERMISSION,
                android.net.Uri.parse("package:" + getPackageName())
            );
            startActivity(intent);
        }
    }

    android.app.AppOpsManager appOps = (android.app.AppOpsManager) getSystemService(android.content.Context.APP_OPS_SERVICE);
    int mode = appOps.checkOpNoThrow(android.app.AppOpsManager.OPSTR_GET_USAGE_STATS, android.os.Process.myUid(), getPackageName());
    if (mode != android.app.AppOpsManager.MODE_ALLOWED) {
        startActivity(new android.content.Intent(android.provider.Settings.ACTION_USAGE_ACCESS_SETTINGS));
    }

    finish(); // মেইন অ্যাক্টিভিটি নিজেকে ধ্বংস করে সাদা স্ক্রিন হাইড করবে
} // <--- এই ব্র্যাকেটটিই আগের বার মিস হয়ে আপনার মেথড বডি ভেঙে দিয়েছিল! এবার এটি একদম নিখুঁত।

